      _run: function(command) { if (root.bar) root.bar.run(command) }
      _setCenterHoverRevealSuppressed: function(value) {
        if (root.bar) root.bar.setCenterHoverRevealSuppressed(value)
      }
    }

    Loader {
      id: loader
      anchors.fill: parent
      source: slot.source
      onLoaded: {
        slot.injectProps()
        Qt.callLater(slot.injectProps)
      }
