import Quickshell
import Quickshell.Io
import qs.services

ShellRoot {
  FileView { id: cfg; path: Quickshell.env("HOME") + "/.config/omarchy/shell.json"; blockLoading: true }
  PluginRegistry {
    id: reg
    firstPartyDir: Quickshell.env("OMARCHY_PATH") + "/shell/plugins"
    shellConfigProvider: function() { return JSON.parse(cfg.text()) }
    onScanFinished: {
      var m = installedPlugins["parker.drawer"]
      console.log("DISCOVERED " + !!m)
      if (m) {
        console.log("KINDS " + JSON.stringify(m.kinds) + " FIRSTPARTY " + !!m.__isFirstParty)
        console.log("ENABLED " + isEnabled("parker.drawer") + " INBAR " + inBar("parker.drawer"))
