cat > $T/shell.qml <<EOF
import QtQuick
import Quickshell
import Quickshell.Io
import qs.Ui

ShellRoot {
  id: top
  function check(name, ok) { console.log((ok ? "PASS " : "FAIL ") + name) }
  FileView { id: cfg; path: Quickshell.env("HOME") + "/.config/omarchy/shell.json"; blockLoading: true }

  // Mimics Bar.qml's popout coordinator and per-plugin activePopout view.
  property var activePopout: null
  property var owned: []
  function requestPopout(o) { if (activePopout === o) return; if (activePopout) { if ("closeForPopoutSwitch" in activePopout) activePopout.closeForPopoutSwitch(); else activePopout.close() } activePopout = o }
  function releasePopout(o) { if (activePopout === o) activePopout = null }
  onActivePopoutChanged: api.activePopout = owned.indexOf(activePopout) !== -1 ? activePopout : (activePopout ? api.foreignPopoutMarker : null)

  PluginBarApi {
    id: api
    pluginId: "parker.drawer"; moduleName: "parker.drawer"
    foreground: "white"; barForeground: "white"; background: "black"; urgent: "red"
    fontFamily: "monospace"; position: "top"; barSize: 26
    _requestPopout: function(o) { if (top.owned.indexOf(o) === -1) top.owned = top.owned.concat([o]); top.requestPopout(o) }
    _releasePopout: function(o) { top.releasePopout(o) }
    _run: function(c) {}
  }
  FakeOther { id: other }

  property var d: null
  Component.onCompleted: {
    var comp = Qt.createComponent("file://$P/Drawer.qml")
    if (comp.status !== Component.Ready) { console.log("FAIL compile " + comp.errorString()); Qt.quit(); return }
    var entry = JSON.parse(cfg.text()).bar.layout.right.filter(function(e) { return e.id === "parker.drawer" })[0]
    var settings = JSON.parse(JSON.stringify(entry)); delete settings.id
    d = comp.createObject(null, { bar: api, moduleName: "parker.drawer", settings: settings })
    waitScan.start()
  }
  Timer {
    id: waitScan; interval: 2500
    onTriggered: {
      check("button visible with default icon", d.implicitWidth > 0 && d.visible)
      check("catalogue scanned (" + Object.keys(d.catalogue).length + " widgets)", !!d.catalogue["omarchy.bluetooth"] && !!d.catalogue["parker.drawer"])
      check("itemIds from shell.json", d.itemIds.join(",") === "omarchy.agents,omarchy.bluetooth,omarchy.monitor,omarchy.weather,omarchy.keyboard-layout")
      var built = d.itemIds.filter(function(id) { return d.hostedItems(id).length === 1 })
      check("all tucked widgets built: " + built.join(","), built.length === 5)
      var bt = d.hostedItems("omarchy.bluetooth")[0]
      check("hosted widget got slot facade", bt.bar && bt.bar.moduleName === "omarchy.bluetooth" && bt.bar.pluginId === "parker.drawer")
      check("broadcast reaches hosted instance", bt.bar.moduleWidgets("omarchy.bluetooth")[0] === bt)
      // popout behaviour
      top.requestPopout(other); check("other popout open", other.opened)
      d.open()
      check("drawer opened and stays open", d.opened)
      check("opening drawer closed other bar popout", !other.opened && top.activePopout === null)
      bt.open()
      check("hosted panel open; drawer stays open", bt.opened && d.opened && d.hostedPopoutOpen)
      top.requestPopout(other)
      check("foreign popout closes drawer + hosted panel", !d.opened && !bt.opened)
      other.close(); top.activePopout = null
      bt.open()
      check("hosted widget opened while shut reopens drawer", d.opened)
      later.start()
    }
  }
  Timer {
    id: later; interval: 200
    onTriggered: {
      check("hosted panel reopened inside drawer", d.hostedItems("omarchy.bluetooth")[0].opened)
      d.close()
      d.settings = { items: ["omarchy.clock", { id: "omarchy.clock", format: "HH:mm" }] }
      Qt.callLater(function() { Qt.callLater(function() {
        var clock = d.hostedItems("omarchy.clock")[0]
        check("items change rebuilds; inline settings applied", d.itemIds.join() === "omarchy.clock" && clock && clock.settings.format === "HH:mm")
        Qt.quit()
      }) })
    }
  }
}
EOF
